// Requer o servidor de desenvolvimento na porta 3000 e um Chrome dedicado com --remote-debugging-port=9222.
import fs from 'node:fs/promises';
const target=Number(process.argv[2]??0);
if(!Number.isInteger(target)||target<0||target>21)throw Error('O índice da plataforma deve estar entre 0 e 21');
const pages=await (await fetch('http://127.0.0.1:9222/json')).json();
const page=pages.find(p=>p.type==='page');
if(!page)throw Error('Nenhuma página de teste do Chrome encontrada');
const ws=new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
let sequence=0;const pending=new Map();
ws.onmessage=({data})=>{const m=JSON.parse(data);if(pending.has(m.id)){const {resolve,reject}=pending.get(m.id);pending.delete(m.id);m.error?reject(Error(JSON.stringify(m.error))):resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
async function evaluate(expression){const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;}
try{
  await send('Page.enable');await send('Emulation.setDeviceMetricsOverride',{width:960,height:580,deviceScaleFactor:1,mobile:false});
  await send('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});
  for(let i=0;i<100;i++){if(await evaluate('document.body?.dataset.ready === "true"'))break;await new Promise(r=>setTimeout(r,100));}
  if(!await evaluate('Boolean(window.review)'))throw Error('A página de revisão não foi inicializada');
  const results=[];
  // Valida todas as plataformas anteriores antes de avançar para a solicitada.
  for(let i=0;i<=target;i++)for(const dt of [0.5,1,1.2]){
    results.push({jump:await evaluate(`window.review.run(${i},${dt})`),
      contacts:await evaluate(`window.review.contacts(${i},${dt})`),
      visual:await evaluate(`window.review.visibleSupport(${i})`)});
  }
  await fs.mkdir('assets/qa-testers/current-screenshots/plataformas',{recursive:true});
  for(const debug of [false,true]){
    await evaluate(`window.review.show(${target},${debug})`);
    const {data}=await send('Page.captureScreenshot',{format:'png'});
    await fs.writeFile(`assets/qa-testers/current-screenshots/plataformas/${String(target).padStart(2,'0')}-${debug?'hitbox':'scene'}.png`,Buffer.from(data,'base64'));
  }
  const detail=await evaluate(`window.review.detail(${target})`);
  await fs.writeFile(`assets/qa-testers/current-screenshots/plataformas/${String(target).padStart(2,'0')}-support.png`,Buffer.from(detail,'base64'));
  const outgoing=[];
  if(target<21)for(const dt of [0.5,1,1.2])outgoing.push(await evaluate(`window.review.run(${target+1},${dt})`));
  await fs.writeFile(`assets/qa-testers/current-screenshots/plataformas/${String(target).padStart(2,'0')}-results.json`,JSON.stringify({results,outgoing},null,2)+'\n');
  await fs.writeFile('assets/qa-testers/current-screenshots/plataformas/results.json',JSON.stringify(results,null,2)+'\n');
  console.log(JSON.stringify({passed:results.length,last:results.slice(-3)},null,2));
}finally{ws.close();}
